{"description":"Inspect current mailboxes and mailman logs while test runs","cmd":"ps aux | grep test_full | grep -v grep | head -3; ls -la /var/mail/ | tail -20; for f in /var/mail/*; do echo "=== $f ==="; if [ -f "$f" ]; then python3 - "$f" <<'PY'
import mailbox,sys
p=sys.argv[1]
try:
    m=mailbox.mbox(p)
    print([(x.get('From'),x.get('Subject')) for x in m])
except Exception as e: print('ERR',e)
PY
fi; done; echo '--- mailman logs ---'; tail -50 /var/log/mailman3/mailman.log 2>/dev/null; echo '--- postfix q ---'; /usr/sbin/postqueue -p 2>&1 | head -80"}
